\label{def:well-shaped}
    Let $\Omega\subset {\mathbb{C}}^n$ be a domain. A \emph{contour of integration} in $\Omega$ is a connected open subset $\mathfrak{C}$ of a totally real smooth submanifold $Y$ of $\Omega$ so that $\mathfrak{C}$ has real dimension $n$ and $\bar{\mathfrak{C}}\subset Y$ and $\partial\mathfrak{C}$ in $Y$ is Lipschitz continuous. Here, a linear subspace $L$ of ${\mathbb{C}}^n$ is \emph{totally real} if $L\cap i L = \{0\}$, see also the paragraph directly after \cite[Def.~9.1.14]{MR4436039}. 

    If $f \in C(\Omega;{\mathbb{R}})$, a contour of integration $\mathfrak{C}$ in $\Omega$ is \emph{strongly well-shaped} for $f$ at $\hat z \in \mathfrak{C}$ if there is $c>0$ so that
    \begin{equation}\label{eq:f_neg_def}
            f(z)-f(\hat z) \leq -c \left\lvertz-\hat z\right\rvert^2
    \end{equation}
    for all $z\in \mathfrak{C}$. 

    If $f \in C^\infty(\Omega;{\mathbb{R}})$, then $\hat z \in \Omega$ is a \emph{saddle point} of $f$ if $d f(\hat z) = 0$ and $\mathrm{sign}(\partial_{(z^{\mathbb{R}},z^{i{\mathbb{R}}})}^2 f)(\hat z) = (n,n)$ (which automatically implies the non-degeneracy of this Hessian). Here $\mathrm{sign}$ is the \emph{signature} of a matrix, which is the pair of amounts of positive and negative eigenvalues of said matrix.

Let $\Omega,\Xi\subset {\mathbb{C}}^n$ be domains, $\hat z \in \Omega, \hat y \in \Xi \cap {\mathbb{R}}^n$ and $\varphi \in \mathcal{O}(\Omega\times \Xi)$. We call $\varphi$ an \emph{FBI phase function at $(\hat z, \hat y)$} if
\begin{enumerate}
	\item $\varphi(\hat z, \hat y) = 0, \partial_y \varphi(\hat z, \hat y) = -\hat \xi \in {\mathbb{R}}^n\setminus\{0\}$,
	\item $\det \partial_{z}\partial_y\varphi(\hat z, \hat y) \neq 0$, 
	\item $\mathrm{Im} \partial_y^2 \varphi(\hat z, \hat y)$ is positive definite.
\end{enumerate}

\label{cor:kerndia}
    There are complex open neighborhoods $U_1$ of $\hat y=0$ and $\varepsilon>0$ so that for $y \in U_1 \cap M$ and $x' \in U_1 \cap \partial M$, we have  
    \[
        K(y,x') = \int e^{i((y'-x')\cdot \eta' + \psi(y,\eta'))} a(y,\eta') \mathrm{d} \eta' + K_a(y,x')\,,\quad K_a \in \mathbfit{O}_{(0,0)}\,,
    \]
    where $a(y,\eta') \in \mathcal{O}(U_1\times \Theta_\varepsilon^\circ)$ is the finite realization of some elliptic classical analytic symbol of order $0$, 
    \begin{equation}\label{eq:symbola}
        a(y,\eta') \sim \sum_{j\geq 0}\left\lvert\eta'\right\rvert^{-j} a_j(y,\left\lvert\eta'\right\rvert^{-1}\eta')\,,\quad  
	(a_j)_{j\in \mathbb{N}} \subset \mathcal{O}(U_1\times U_2)\,,\quad a_j(y',0,\eta') = (2\pi)^{1-n}\delta_{0j}\,,\quad a(y',0,\eta')=(2\pi)^{1-n}\,,
    \end{equation}
    and $\psi = \phi - y'\cdot \eta'$, where $\phi \in \mathcal{O}(U_1\times \Theta_\varepsilon)$ is homogeneous of degree $1$ in $\eta'$ and satisfies 
    \begin{equation}\label{eq:phi2}
		\phi(y',0,\eta') = y'\cdot\eta'\,,\quad \partial_{y_n}\phi(y,\eta') =  ir^{1/2}(y,\partial_{y'}\phi(y,\eta'))\,.
    \end{equation}

\label{thm:localsymb}
    Let $q\in L^\infty(M)$. For any $\xi'_0 \in S^{n-2}$ fixed the following two statements are equivalent
    \begin{enumerate}
	\item $\dot \Lambda_q$ is analytic off $\Delta_W$ near $(0,0)$ and $\sigma_a^q(x',h^{-1}\tau \xi'_0)$ is a cl.a.s. of order $-1$ for $(x',\tau)$ near $(0,1)$
	\item there is some $\tilde{q} \in C_c^\infty({\mathbb{R}}^n), \tilde{q}$ analytic near $0$ so that in normal coordinates in $W$ we have $q = \mathbb{1}_{\{y_n\geq 0\}}\tilde{q}$ near $\hat y=0$. 
    \end{enumerate}
    Furthermore, in this case $\sigma_a^q(x',h^{-1}\tau \xi'_0)$ is elliptic near $(x',\tau)=(0,1)$ if and only if $\tilde{q}(0) \neq 0$.

\label{lem:tdTinvnew}
	Defining, with $z = (z',z_n)$, 
	\begin{equation}\label{eq:def_phi4}
		\phi_4(z,w,x)\coloneqq \phi_2(w,x)-\hat\phi(z,x)\,,\quad\text{and}\quad	\Phi^{\sharp}(z)\coloneqq \frac{\hat c}{2}((z')^{{\mathbb{R}}})^2\,, 
	\end{equation}
	there is some smooth exponent weight $\Phi^{\sharp,\ast}$ so that $(\phi_4, \Phi^\sharp, \Phi^{\sharp,\ast})$ is a Sj\"ostrand triad (\cite[Def.~20.5.1]{MR4436039}) at $(\hat z, \hat w, \hat x) = (0,(0,1),0)$ and $-\partial_z \phi_4(\hat z, \hat w, \hat x) = -2i\partial_z\Phi^\sharp(\hat w, \hat x)=0$, and 
	\[
		\det \begin{pmatrix}\partial_z\partial_w\phi_4 & \partial_z\partial_x \phi_4 \\ \partial_w\partial_x\phi_4 & \partial_x^2\phi_4
		\end{pmatrix}(\hat z, \hat w, \hat x)\neq 0\,.
	\]

\label{lem:contour}
    For $\hat c>0$ sufficiently large, there is $\rho_0>0$ so that for all $\rho \in (0,\rho_0]$,
    \begin{enumerate}
        \item The contour $\mathfrak{C}_\rho$ is strongly well-shaped at $(0,0)$ for $\Psi_1$.
        \item Let $\Phi(x) \coloneqq -\phi_2^{i{\mathbb{R}}}(\hat w, x)$. There is a constant $c_0\in {\mathbb{C}}\setminus\{0\}$ depending only on $\hat c>0$ and the dimension $n$ so that with $c_h \coloneqq c_0 h^n$, there is a compact $K\subset B_\rho$ and complex open neighborhood $U$ of $0$ and $C,\varepsilon >0$ so that for all $g\in \mathcal{O}^{(\Phi)}(B_\rho)$,
        \[
            \int_{\mathfrak{C}_{\rho/2}} e^{\frac{i}{h}(\hat \phi(z,y)-\hat\phi(z,x))} g(x;h) \mathrm{d} z\mathrm{d} x - c_h g(y;h) \in \mathcal{O}^{(-\omega)}(U)\,,
        \]
        and the LHS above is bounded on $U$ by $Ce^{-\varepsilon/h} \sup_{x\in K} e^{-\Phi(x)/h}\left\lvertg(x;h)\right\rvert$. 
    \end{enumerate}

\label{lem:replace}
    Let $\hat c>0$ be sufficiently large and $\rho \in (0,\rho_0]$ with $\rho_0$ sufficiently small. 
    \begin{enumerate}
        \item The integral \cref{eq:germFIO} defines a classical elliptic germ FIO transform 
        \[
            \mathcal{T} \colon \mathbfit{O}^{(\Phi^\sharp)}_0/\mathbfit{O}^{(-\omega)}_0 \to \mathbfit{O}^{(\Phi^{\sharp,\ast})}_{\hat w}/\mathbfit{O}^{(-\omega)}_{\hat w}
        \]
        that is invertible on these spaces.
        \item If $u\in L_{c,+}^\infty({\mathbb{R}}^n)$ has support sufficiently contracted about $0$, then for $A$ from \cref{eq:defofAFBI},
        \[
            \mathcal{T}_{\rho}(Au) - Su\in \mathbfit{O}^{(-\omega)}_{\hat w}\,.
        \]
    \end{enumerate}

We remark first that since we assumed that $P$ does not have Dirichlet eigenvalue $0$ on $M$, it does not have Dirichlet eigenvalue $0$ on each connected component of $M$. Thus, in order to show that $q = 0$ a.e. in $M$, it suffices to assume that $M$ is connected, because one may use the same argument for each connected component of $M$. We thus assume that $M$ is connected.

    We shall follow \cite{zbMATH05707695} and \cite{feizmohammadi2024partialdatainverseproblems}. Let $y_1 \in M^{\mathrm{int}}$ be fixed arbitrarily and choose $y_0 \in \partial M$ so that $\partial M$ is analytic near $y_0$ and there is $\gamma \colon [0,1] \to M$ smooth with $\gamma(0)=y_0, \gamma(1) = y_1$ and $\gamma((0,1]) \subset M^{\mathrm{int}}$, and $\gamma$ is non-self-intersecting.  
    Introduce analytic boundary normal coordinates in some open neighborhood $W$ of $y_0$ in $M$. We may assume that $W\cap \partial M\subset 
    \Sigma$ for $\Sigma\ni y_0$ from the statement of \cref{thm:harmonic}.

    Define $\Gamma_\varepsilon(s) \coloneqq \{y \in M \colon d_g(\gamma([0,s]),y) \leq \varepsilon\}$ for $s\in [0,1]$ and $\varepsilon>0$. According to \cref{thm:localmain}, if $\delta>0$ is sufficiently small we know that $\mathrm{ess}\ \mathrm{supp} q \cap B^M_{\delta}(y_0) = \emptyset$. In particular, if $\varepsilon>0$ is sufficiently small and we define the closed set
    \[
	    J = \{t \in [0,1]\colon q = 0 \ \text{a.e. on}\  \Gamma_\varepsilon(t)\}\,,
    \]
    then there is some $s_0 \in J$ with $s_0>0$ and $\Gamma_\varepsilon(1) \cap \partial M \subset B_\delta^M(y_0)$ (where we use that $\gamma((0,1])\subset M^{\mathrm{int}}$). We assume also that $\varepsilon>0$ is smaller than half the injectivity radius of $M$. We keep this choice of $\varepsilon>0$ fixed from now onward. We conclude that if $\varepsilon_0>0$ is sufficiently small, then 
    \[
        B_{\varepsilon_0}^M(\{y \in M\colon d_g(\gamma([s_0,1]),y) \leq \varepsilon\}) \cap \partial M = \emptyset\,,
    \]
    and fix this $\varepsilon_0>0$. 

    Note that the set $J$ defined above is non-empty and closed: the only non-trivial argument to prove this occurring when $(t_j)_{j\in\mathbb{N}}\subset J$ is an increasing sequence converging to some $t \in (0,1]$ and we wish to show $t\in J$. In this case, $\Gamma_\varepsilon(t)\setminus \bigcup_{j\geq 1}\Gamma_{\varepsilon}(t_j) \subset \partial B_{\varepsilon}(\gamma(t))$, which has volume zero and thus $q=0$ a.e. there, proving that $t\in J$, and thus $J$ is closed. 

    Showing that $J$ is open implies that $\mathrm{ess}\ \mathrm{supp} q$ is empty in a neighborhood of $y_1$. Since $y_1 \in M^{\mathrm{int}}$ was chosen arbitrarily, the proof would then be complete.

    Assume that $s \in J$. If $s< s_0$, then by our definition of $J$ we know that $[0,s_0] \subset J$ so that an open neighborhood of $s$ lies in $J$. We may thus assume that $s\geq s_0$. Also fix some $\varepsilon' \in (\varepsilon/2,\varepsilon)$.

    It is possible to define a compact manifold $M' \subset M$ so that 
    \begin{enumerate}
        \item $M'$ and $M \setminus M'$ are connected, $q$ vanishes a.e. on $M\setminus M'$, 
        \item $\partial M'$ is smooth,
        \item $P$ does not have Dirichlet eigenvalue $0$ on $M'$,
        \item $\partial M' \supset (\partial B_\varepsilon^M(\gamma(s))\setminus \Gamma_{\varepsilon'}(s))$,
        \item and the boundary of $M'$ is analytic in $\partial B_\varepsilon^M(\gamma(s))\setminus \Gamma_{\varepsilon'}(s)$.
    \end{enumerate}
