    To construct $M'$, merely start with 
    \[
        M_0 = M\setminus \left(B_{\varepsilon}^M(\gamma(s))\cup B^M_{\varepsilon/2}(\gamma([0,s]))\right)\,,
    \]
    which satisfies properties 1., 4. and 5, see \cref{fig:fig}. By smoothing out the boundary of $M_0$ near $\partial B_\varepsilon^M(\gamma(s))\cap \Gamma_{\varepsilon/2}(s)$ within $\Gamma_{\varepsilon'}(s)\setminus \Gamma_{\varepsilon/2}(s)$ and otherwise slightly modifying $M_0$ away from $B_\varepsilon^M(\gamma(s))$ (see \cref{cor:perturbDEV}), making sure these modifications occur only where we know $q=0$ a.e., one obtains $M'$ with the desired properties. 

    Recall that the proof is complete if we can show that every $x \in \partial B_\varepsilon^M(\gamma(s))$ has an open neighborhood on which $q$ vanishes. When $x \in \partial B_\varepsilon^M(\gamma(s))\cap \Gamma_{\varepsilon'}(s)$, since $\varepsilon'<\varepsilon$ we have $B_{\varepsilon-\varepsilon'}(x)\subset \Gamma_\varepsilon(s)$ and $q=0$ a.e. there already. 

    We thus assume that $x\in \partial B_\varepsilon^M(\gamma(s))\setminus \Gamma_{\varepsilon/2}(s) \subset \partial M'$ where we used property 4. of $M'$. As a consequence of Runge approximation (\cref{thm:runge} applied to $L=-P$, wherein we choose $\Xi = \emptyset$ which allows taking $\Gamma \subset \Sigma$ with $\partial M\setminus \bar M'\subset \Gamma\subset B_\delta^M(y_0)\cap \partial M$ for $\delta>0$ small), if $K_{M'}$ is the Poisson operator for $P$ on $M'$, for any $f\in H^{r+3/2}(\partial M')$ with $\mathrm{supp} f\vert_{\partial M\cap M'} = \emptyset$ there is a sequence $(f_j)_{j\in\mathbb{N}} \subset H^{r+3/2}(\partial M)$ with $\mathrm{supp} f_j \subset \Sigma$ so that $K(f_j)\vert_{M'} \to K_{M'}(f)$ in $H^{r+2}$ for all $r\geq 0$. 

    Introduce analytic boundary normal coordinates near $x$ in $M'$. Performing the constructions of \cref{prop:K1,prop:K2} on $M'$ in these coordinates, and using that $q = 0$ on $M\setminus M'$, we have 
    \[
        \int_{M'} q \overline{K_{M'}(\chi e^{\frac{i}{h}\psi_0})} K_{M'}(\tilde{\chi}_{j_\vartheta(h)} e^{\frac{i}{h}\psi_1}) \mathrm{d} V_g(y) = \lim_{j,k \to \infty}\int_M q \overline{K(f_{1,j})} K(f_{2,k}) \mathrm{d} V_g(y) = 0\,,
    \]
    where $(f_{1,j})_{j\in\mathbb{N}},(f_{2,k})_{k\in\mathbb{N}} \subset C^\infty_c(\Sigma)$. Invoking the local \cref{thm:localmain} with $M$ replaced by $M'$, we find that $q$ vanishes near $x$. By compactness, we have shown that there is some $\varepsilon_0>0$ so that $q$ vanishes on $B_{\varepsilon+\varepsilon_0}(\gamma(s))$, which implies that the set $J$ is open. The proof is complete.

\label{prop:allthingst}
	Let $\xi'_0\in S^{n-2}$ be arbitrary and fixed. There is an open complex neighborhood $\hat U$ of $(0,1)\times {\mathbb{C}}^n$ in ${\mathbb{C}}^{n-1}\times {\mathbb{C}}\times {\mathbb{C}}^n$ and a formal cl.a.s $\underline{t}(y',\tau,\eta;h) = h\sum_{k\geq 0}h^k t_{k}(y',\tau,\eta)$ with $(t_k)_{k\in\mathbb{N}} \subset \mathcal{O}(\hat U)$ (and fiber variable $\tau$), and a continuous function $t(y',\tau,\eta;h)$ so that for all complex $\tau$ sufficiently near $1$ and for every sufficiently small compact complex neighborhood $K$ of $0$ there is $C>0$ so that for all $C_0>0$ sufficiently large, all $N\in\mathbb{N}$, and all $h > 0$ so that $C_0hN \leq 1/2-\varepsilon_0$, we have
	\begin{equation}\label{eq:tpolybound}
		\sup_{y'\in K}\left\lverth^{-1}t- \sum^{N-1}_{k=0} h^k t_k\right\rvert \leq C^{N+1} h^N \sum_{j=0}^Nj!\left\lvert\eta\right\rvert^{N-j}\,.
	\end{equation}
	The function $t_0$ is non-vanishing and $t_{k}(y',\tau,\eta)$ is a polynomial of degree $k$ in $\eta$ with holomorphic coefficients (in $y',\tau$). Writing $t_{k,j}$ for the $j$-th order homogeneous part of $t_k$ ($j\leq k$), we have
	\begin{equation}\label{eq:boundsont_k}
		\left\lvertt_{k,j}\right\rvert\leq C^{k+1} (k-j)! \left\lvert\eta\right\rvert^j\,,\qquad \left\lvertt_k\right\rvert \leq C^{k+1} k! \left\lvert\eta\right\rvert^k_+\,.
	\end{equation}

	Finally, for any $q \in C_c^\infty({\mathbb{R}}^n)$ having sufficiently small support near the origin we have
	\begin{equation}\label{eq:sigmaist}
		\tau \in {\mathbb{R}}\ \text{near}\ 1 \implies T(\mathbb{1}_{\{y_n\geq 0\}}q)(x',h^{-1}\tau\xi'_0) = \iint e^{i(x'-y)\cdot\eta} t(y',\tau,\eta;h) q(y)\mathrm{d}\eta \mathrm{d} y
	\end{equation}
	for each $h>0$ small enough, where
	\[
		 \iint e^{i(x'-y)\cdot\eta} t(y',\tau,\eta;h) q(y)\mathrm{d}\eta \mathrm{d} y = \iint e^{i(x'-y)\cdot\eta} (1+\left\lvert\eta\right\rvert^2)^{-k}(1+\Delta_y)^{k}\left(t(y',\tau,\eta;h) q(y)\right)\mathrm{d}\eta \mathrm{d} y
	\]
	is defined as an oscillatory integral for $k\in \mathbb{N}$ sufficiently large. Above, we wrote $(x'-y)$ for $((x',0)-y)$.

\label{lem:rhoprops}
	Let $\xi'_0\in S^{n-2}$ be arbitrary and fixed. Using notation from \cref{cor:kerndia}, define for $\tau \in {\mathbb{R}}$ near $1$, 
	\[
		\rho(y',z_n,\tau,\eta';h) \coloneqq i(\psi(y',hz_n,h^{-1}\tau\xi'_0)-\psi^\ast(y',hz_n,h^{-1}(h\eta'+\tau\xi'_0)))\,.
	\]
	For any integer $k\geq 0$, $\partial^k_h e^\rho\vert_{h=0}$ is a polynomial of degree $k$ in $\eta'$ with analytic coefficients (in $\tau$ as well) and for every complex compact neighborhood $K$ of $0$ there are $C,c>0$ so that for any integer $k \geq 0$,  
	\begin{equation}\label{eq:etabounds}
		\sup_{y'\in K}\left\lvert\partial^k_h e^\rho\vert_{h=0}\right\rvert \leq C^{k+1} k!  e^{-z_n c}\sum_{j=0}^k \left\lvertz_n\right\rvert^j\left\lvert\eta'\right\rvert^{k-j}\,.
	\end{equation}
	For any integers $j,k\geq 0$,
	\begin{equation}\label{eq:rhoboundwithint}
		\int_0^\infty \left\lvertz_n\right\rvert_+^j \left\lvert\frac{\partial_h^k e^{\rho}}{k!}\vert_{h=0}\right\rvert\mathrm{d} z_n \leq C^{k+j+1} j! \sum_{s=0}^k s!\left\lvert\eta'\right\rvert^{k-s}\,.
	\end{equation}
	In addition, let $\chi \in C^\infty_c({\mathbb{R}})$ be identically $1$ in $\left\lvertz_n\right\rvert \leq \varepsilon_0/2$ and vanish in $\left\lvertz_n\right\rvert \geq \varepsilon_0$. For every $j,N\in\mathbb{N}$ and every compact $K$ we have, for $\tau \in {\mathbb{R}}$ near $1$,
	\begin{equation}\label{eq:rhodiffint}
		\sup_{y'\in K}\left\lvert\int_0^\infty \left\lvertz_n\right\rvert_+^j \left(e^\rho - \sum_{k=0}^{N-1} h^k \frac{\partial_h^k e^\rho\vert_{h=0}}{k!}\right)\chi\mathrm{d} z_n\right\rvert \leq C^{N+j+1}h^Nj!\sum_{s=0}^N s!\left\lvert\eta'\right\rvert^{N-s}\,.
	\end{equation}

\label{lem:justt}
	Let $\xi'_0\in S^{n-2}$ be arbitrary and fixed. Let $\chi \in C^\infty_c({\mathbb{R}})$ be identically $1$ in $\left\lvertz_n\right\rvert \leq \varepsilon_0/2$ and vanish in $\left\lvertz_n\right\rvert \geq \varepsilon_0$. Define for $\tau \in {\mathbb{R}}$ near $1$, 
	\begin{equation}\label{eq:definet}
		\begin{gathered}
		t(y',\tau,\eta;h)\coloneqq \\  
		(2\pi)^{n-2}\int_0^\infty e^{i(\psi(y',z_n,h^{-1}\tau\xi'_0)-\psi^\ast(y',z_n,\eta'+h^{-1}\tau\xi'_0)+z_n\eta_n)}a(y',z_n,h^{-1}\tau\xi'_0)a^\ast(y',z_n,\eta'+h^{-1}\tau\xi'_0)\chi(z_n)\mathrm{d} z_n\,,
		\end{gathered}
	\end{equation}
	which is holomorphic with respect to $y'$ near $0$ for any fixed $\eta\in {\mathbb{R}}^{n}$ and jointly continuous in $(y',\tau,\eta')$ for $y'$ near $0$ and all $\eta \in {\mathbb{R}}^n$. Furthermore, for any $k\geq 0$ define
	\begin{equation}\label{eq:tkformula}
			t_k(y',\tau,\eta) \coloneqq (2\pi)^{-1}\sum_{s+j+l=k} \int_0^\infty b_l(y',z_n,\tau,\eta') \frac{\partial_h^j (e^{\rho(y',z_n,\tau,\eta';h)})}{j!}\vert_{h=0} \frac{(iz_n\eta_n)^s}{s!} \mathrm{d} z_n\,.
	\end{equation}
	We have $t_0(y',\tau,\eta) = (2\pi)^{-n}(2r^{1/2}(y',0,\tau\xi'_0))^{-1}$ and the function $t_k$ is a polynomial of degree $k$ with respect to $\eta$ and we denote by $t_{k,j}$ the $j$-th order homogeneous term of $t_k$ for any $0\leq j\leq k$. For some $C>0$ independent of all variables we have
	\begin{equation}\label{eq:boundsont_kOLD}
		\left\lvertt_{k,j}\right\rvert\leq C^{k+1} (k-j)! \left\lvert\eta\right\rvert^j\,,\qquad \left\lvertt_k\right\rvert \leq C^{k+1} k! \left\lvert\eta\right\rvert^k_+\,,
	\end{equation}
	and each $t_k$ depends holomorphically on $\tau$ for $\tau$ near $1$ and each $t_k$ is positively homogeneous of degree $-k-1$ in $\tau$. 

	Finally, for any complex compact neighborhood $K$ of $0$, for every sufficiently large $C_0>0$, any $N$, and any $h>0$ so that $C_0hN \leq 1/2-\varepsilon_0$, there is some $C>0$ so that
	\begin{equation}\label{eq:diffboundt}
		\sup_{y'\in K}\left\lverth^{-1}t - \sum_{k=0}^{N-1} h^k t_k\right\rvert \leq C^{N+1}h^N \sum_{s=0}^N s!\left\lvert\eta\right\rvert^{N-s}\,.
	\end{equation}

\label{prop:sigmatotq}
	Let $\xi'_0\in S^{n-2}$ be fixed and $\tau\in {\mathbb{C}}$ near $1$. 

	If $\tilde{q} \in C_c^\infty({\mathbb{R}}^n)\cap C^\omega(U)$ where $U$ is an open neighborhood of $0$ has support sufficiently near $0$, then $h\sum_{k\geq 0}h^k\mathrm{Op}^R(t_k)\tilde{q}(x',0)$ is a formal cl.a.s. of order $-1$ defined in an open complex neighborhood of $(0,1)$ and $\sigma_a^{\mathbb{1}_{\{y_n\geq 0\}}\tilde{q}}(x';h^{-1}\tau\xi'_0) \sim h\sum_{k\geq 0}h^k\mathrm{Op}^R(t_k)\tilde{q}(x',0)$ there.

\label{lem:recoversymbol}
	Let $m\in{\mathbb{R}}$ and $p(x,\xi) \sim \sum_{k\geq 0} p_k(x,\xi)$ be a formal classical analytic symbol in $\Omega\times \Gamma$ according to \cref{def:sym}, where each $p_k$ is positively homogeneous of degree $m-k$ in $\xi$, and let $p\sim \underline{p}$ be a cl.a.s. 

	For every compact subset $K\Subset \Omega\times \Gamma$ and every sufficiently large $C_0>0$ there is $C>0$ so that for every $N\in\mathbb{N}, N\geq 1$ and $r\geq C_0N$ we have
	\begin{equation}\label{eq:RNerr}
		\sup_K\left\lvertp(x,r\xi)-\sum_{k=0}^{N-1} r^{m-k}p_k(x,\xi)\right\rvert\leq C^{N+1}N!r^{m-N}\,.
	\end{equation}

\label{thm:DEV}
	Let $(M,g)$ be a compact Riemannian manifold with smooth boundary. Let $L$ be a strongly elliptic formally self-adjoint differential operator with smooth coefficients on $M$ of even order $m$. For each non-empty open $U \subset M$ with $C^{\infty}$ boundary, the Dirichlet realization of $L$ in $L^2(U)$, i.e. the restriction of $L$ to the domain $H^m(U) \cap H^{m/2}_0(U)$ has real discrete spectrum bounded below and unbounded above: one may enumerate the eigenvalues $\lambda_1(U) \leq \lambda_2(U) \leq \dots \subset {\mathbb{R}}$ counted according to multiplicity.

    Furthermore, for any $U_1, U_2 \subset M$ open sets with $C^{\infty}$ boundary,
    \begin{enumerate}
        \item if $U_1 \subset U_2$, then $\lambda_k(U_1) \geq \lambda_k(U_2)$ for all $k\in \mathbb{N}$, and $\lambda_k(U_1) = \lambda_k(U_2)$ for all $k$ implies $U_1 = U_2$.
        \item For any sequence of open sets $W_j \subset M, j\in\mathbb{N}$ each having $C^{\infty}$ boundary so that $W_j \subset W_{j+1} \forall j$ and $W \coloneqq \bigcup_{j\geq 1}W_j$ has $C^{\infty}$ boundary, we have $\lambda_k(W_j) \to \lambda_k(W)$ as $j\to\infty$ for all $k\in \mathbb{N}$.
    \end{enumerate}
    Assume in addition that $L$ satisfies the following unique continuation property: for any connected open $G\subset M$, $\lambda\in{\mathbb{R}}$, and any $u \in H^m(G)\cap H^{m/2}_0(G)$ satisfying $L u = \lambda u$ in $G$ and vanishing on some open subset of $G$, we have $u\equiv 0$ on $G$. This additional assumption implies that
    \begin{enumerate}\setcounter{enumi}{2}
        \item If $U_1 \subset U_2$ and $U_2\setminus U_1$ contains an open set and $U_2$ is connected, then $\lambda_k(U_1) > \lambda_k(U_2)$ for all $k\in \mathbb{N}$.
    \end{enumerate}

\label{thm:runge}
	Let $(M,g)$ be a connected compact Riemannian manifold with smooth boundary, let non-empty $U \subset M$ be open, so that $U$ has smooth boundary, $M\setminus \bar U$ is connected, and $\partial M \setminus \bar U$ has non-empty interior. Let $\Xi \subset \bar U \cap \partial M$ be closed in $\partial M$ (we allow $\Xi$ to be empty) and let $\Gamma\subset \partial M$ be open with $\Gamma \supset \Xi$ and $\Gamma \cap (M\setminus \bar U) \neq \emptyset$ so that $\Gamma \cup (\partial M \cap \bar U)$ is open in $\partial M$. Let $\Gamma_0 \subset \Gamma\setminus \bar U$ be a non-empty open subset of $\partial M$. Let $L$ be a strongly elliptic formally self-adjoint differential operator with smooth coefficients on $M$ of even order $m$ so that
	\begin{enumerate}
	\item $L$ does not have Dirichlet eigenvalue $0$ (restricted to $M$).
	\item We assume the following unique continuation property: any $u \in C^\infty((M^{\mathrm{int}}\setminus \bar U)\cup \Gamma_0)$ so that $L^\ast u = 0$ in $M^{\mathrm{int}}\setminus \bar U$ and $\partial_\nu^j u\vert_{\Gamma_0} = 0 \forall j\geq 0$ vanishes in $M^{\mathrm{int}}\setminus \bar U$.
	\end{enumerate}
	For any $s \geq m$, the set
	\[
		\mathcal{R} = \left\{u\vert_U \colon u\in H^s(M), L u = 0\ \text{in}\ M, (\partial_\nu^j u\vert_{\partial M})_{j=0}^{m/2-1} \in C_c^\infty(\Gamma)^{m/2}\right\}
	\]
	is dense in 
    \[
        \mathcal{S} = \left\{u \in H^s(U) \colon Lu = 0 \ \text{in}\ U, (\partial_\nu^j u\vert_{(\partial M \cap \bar U)\setminus \Xi})_{j=0}^{m/2-1} = 0\right\}
    \]
    in the $H^s(U)$ norm.
